// Narration-driven timeline. Generated by `python -m musevid.produce ... --stages cues`.
// Never hand-edit frame numbers: change beats.json / script.json and regenerate.
export type Word = {word: string; start: number; end: number};
export type Production = {
	name: string;
	title: string;
	fps: number;
	width: number;
	height: number;
	durationInFrames: number;
	cues: Record<string, {t: number; frame: number; word: string; line: string}>;
	lines: {id: string; start: number; end: number; words: Word[]}[];
	mouth: number[];
};

export const makeCue = (p: Production) => (name: string): number => {
	const c = p.cues[name];
	if (!c) throw new Error(`unknown cue "${name}" — add it to beats.json`);
	return c.frame;
};

export const lineFrames = (p: Production, id: string) => {
	const l = p.lines.find((x) => x.id === id);
	if (!l) throw new Error(`unknown line ${id}`);
	return {start: Math.round(l.start * p.fps), end: Math.round(l.end * p.fps)};
};

export const mouthAt = (p: Production, frame: number) => p.mouth[Math.max(0, Math.min(p.mouth.length - 1, frame))] ?? 0;
